package io.infranexum.ddi.ipam.application;

import io.infranexum.core.contracts.*;
import io.infranexum.core.events.*;
import io.infranexum.ddi.ipam.domain.*;
import io.infranexum.ddi.ipam.ports.*;
import java.math.BigInteger;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.time.*;
import java.util.*;

/** PGM-08-E01 application boundary for atomic IPAM allocation and routing-space governance. */
public final class IpamApplicationService {
 private static final ContractVersion EVENT_VERSION=ContractVersion.parse("1.0.0"); private static final EventSource SOURCE=new EventSource("infranexum.ddi.ipam");
 private final IpamRepository repository; private final IpamIdempotencyRepository idempotency; private final IpamFeaturePolicy features; private final IpamReferencePolicy references; private final TransactionalEventStore events; private final UuidV7Generator ids; private final Clock clock; private final MemorableCodeGenerator codes=new MemorableCodeGenerator();
 public IpamApplicationService(IpamRepository repository,IpamIdempotencyRepository idempotency,IpamFeaturePolicy features,IpamReferencePolicy references,TransactionalEventStore events,UuidV7Generator ids,Clock clock){this.repository=Objects.requireNonNull(repository);this.idempotency=Objects.requireNonNull(idempotency);this.features=Objects.requireNonNull(features);this.references=Objects.requireNonNull(references);this.events=Objects.requireNonNull(events);this.ids=Objects.requireNonNull(ids);this.clock=Objects.requireNonNull(clock);}
 public IpamVrf createVrf(CreateVrfCommand c,IpamCommandContext ctx){enabled();references.requireOrganization(c.organizationId());String requested=optionalCode(c.code());String fp=fingerprint("vrf.create",c.organizationId(),requested==null?"<auto>":requested,c.displayName(),c.routeDistinguisher());return execute(tx->{var prior=idempotency.find(ctx.idempotencyKey());if(prior.isPresent())return replayVrf(prior.orElseThrow(),fp,"vrf.create");if(repository.countVrfs()>=features.vrfLimit())throw conflict("DDI_VRF_QUOTA","VRF quota reached");DomainIdentifier id=ids.next();String code=requested==null?codes.generate(c.displayName(),id):requested;if(repository.vrfCodeExists(c.organizationId(),code))throw conflict("DDI_VRF_DUPLICATE","VRF code already exists");var v=IpamVrf.draft(id,c.organizationId(),code,c.displayName(),c.routeDistinguisher(),clock.instant());repository.insertVrf(v);tx.append(event("ddi.ipam.vrf.created.v1",v.id(),v.organizationId(),ctx,"\"code\":\""+json(v.code())+"\""));remember(ctx,fp,"vrf.create",v.id());return v;});}
 public IpamVlan createVlan(CreateVlanCommand c,IpamCommandContext ctx){enabled();references.requireOrganization(c.organizationId());references.requireSiteIfPresent(c.organizationId(),null,c.siteId());String fp=fingerprint("vlan.create",c);return execute(tx->{var prior=idempotency.find(ctx.idempotencyKey());if(prior.isPresent())return replayVlan(prior.orElseThrow(),fp,"vlan.create");if(repository.countVlans()>=features.vlanLimit())throw conflict("DDI_VLAN_QUOTA","VLAN quota reached");var v=IpamVlan.draft(ids.next(),c.organizationId(),c.siteId(),c.vlanId(),c.vni(),c.name(),clock.instant());if(repository.vlanExists(c.organizationId(),v.vlanId(),v.vni()))throw conflict("DDI_VLAN_DUPLICATE","VLAN/VNI already exists");repository.insertVlan(v);tx.append(event("ddi.ipam.vlan.created.v1",v.id(),v.organizationId(),ctx,"\"name\":\""+json(v.name())+"\""));remember(ctx,fp,"vlan.create",v.id());return v;});}
 public IpamNetwork createNetwork(CreateNetworkCommand c,IpamCommandContext ctx){enabled();references.requireOrganization(c.organizationId());references.requireSubdivisionIfPresent(c.organizationId(),c.subdivisionId());references.requireSiteIfPresent(c.organizationId(),c.subdivisionId(),c.siteId());IpCidr cidr=new IpCidr(c.cidr());String fp=fingerprint("network.create",c,cidr);return execute(tx->{var prior=idempotency.find(ctx.idempotencyKey());if(prior.isPresent())return replayNetwork(prior.orElseThrow(),fp,"network.create");if(repository.countNetworks()>=features.prefixLimit())throw conflict("DDI_PREFIX_QUOTA","prefix quota reached");IpamVrf vrf=requireVrf(c.vrfId());if(!vrf.organizationId().equals(c.organizationId()))throw conflict("DDI_SCOPE_MISMATCH","VRF belongs to another organization");if(c.vlanId()!=null){IpamVlan vlan=requireVlan(c.vlanId());if(!vlan.organizationId().equals(c.organizationId()))throw conflict("DDI_SCOPE_MISMATCH","VLAN belongs to another organization");}repository.lockRoutingEnvironment(c.organizationId(),c.vrfId());DomainIdentifier overlapExclusion=null;if(c.parentNetworkId()!=null){IpamNetwork parent=requireNetwork(c.parentNetworkId());if(!parent.vrfId().equals(c.vrfId())||!parent.cidr().contains(cidr))throw conflict("DDI_PARENT_CONTAINMENT","network must be contained in parent within the same VRF");overlapExclusion=parent.id();}if(repository.networkOverlaps(c.organizationId(),c.vrfId(),cidr,overlapExclusion))throw conflict("DDI_CIDR_OVERLAP","network overlaps another active routing-space prefix");var n=IpamNetwork.draft(ids.next(),c.organizationId(),c.subdivisionId(),c.siteId(),c.vrfId(),c.vlanId(),c.parentNetworkId(),c.kind(),cidr,c.usage(),c.trustLevel(),clock.instant());repository.insertNetwork(n);tx.append(event("ddi.ipam.network.created.v1",n.id(),n.organizationId(),ctx,"\"cidr\":\""+json(n.cidr().value())+"\",\"vrf_id\":\""+n.vrfId()+"\""));remember(ctx,fp,"network.create",n.id());return n;});}
 public IpamPool createPool(CreatePoolCommand c,IpamCommandContext ctx){enabled();String fp=fingerprint("pool.create",c);return execute(tx->{var prior=idempotency.find(ctx.idempotencyKey());if(prior.isPresent())return replayPool(prior.orElseThrow(),fp,"pool.create");IpamNetwork n=requireNetwork(c.networkId());if(!n.organizationId().equals(c.organizationId())||n.kind()!=NetworkKind.SUBNET||n.status()!=IpamStatus.ACTIVE)throw conflict("DDI_POOL_NETWORK_INVALID","pool requires an active subnet in the same organization");String start=IpCidr.canonicalAddress(c.startAddress()),end=IpCidr.canonicalAddress(c.endAddress());if(!n.cidr().containsAddress(start)||!n.cidr().containsAddress(end)||compareIp(start,end)>0)throw conflict("DDI_POOL_RANGE_INVALID","pool must be ordered and contained in subnet");repository.lockRoutingEnvironment(c.organizationId(),n.vrfId());if(repository.poolOverlaps(n.id(),start,end))throw conflict("DDI_POOL_OVERLAP","pool overlaps another active pool");var p=IpamPool.active(ids.next(),c.organizationId(),n.id(),start,end,c.name(),clock.instant());repository.insertPool(p);tx.append(event("ddi.ipam.pool.created.v1",p.id(),p.organizationId(),ctx,"\"network_id\":\""+p.networkId()+"\""));remember(ctx,fp,"pool.create",p.id());return p;});}
 public IpamAddress allocate(AllocateAddressCommand c,IpamCommandContext ctx){enabled();references.requireOrganization(c.organizationId());references.requireRsotIfPresent(c.organizationId(),c.rsotObjectId());references.requireDcimEquipmentIfPresent(c.organizationId(),c.dcimEquipmentId());String fp=fingerprint("address.allocate",c);return execute(tx->{var prior=idempotency.find(ctx.idempotencyKey());if(prior.isPresent())return replayAddress(prior.orElseThrow(),fp,"address.allocate");if(repository.countAddresses()>=features.addressLimit())throw conflict("DDI_ADDRESS_QUOTA","IP address quota reached");IpamNetwork n=requireNetwork(c.networkId());if(!n.organizationId().equals(c.organizationId())||!n.vrfId().equals(c.vrfId())||n.kind()!=NetworkKind.SUBNET||n.status()!=IpamStatus.ACTIVE)throw conflict("DDI_ADDRESS_NETWORK_INVALID","address requires active subnet in same routing environment");IpamPool pool=c.poolId()==null?null:requirePool(c.poolId());if(pool!=null&&!pool.networkId().equals(n.id()))throw conflict("DDI_POOL_SCOPE_MISMATCH","pool does not belong to network");repository.lockRoutingEnvironment(c.organizationId(),c.vrfId());String ip; if(c.requestedAddress()==null||c.requestedAddress().isBlank()){if(pool==null)throw conflict("DDI_POOL_REQUIRED","automatic allocation requires an IPAM pool");repository.lockPool(pool.id());pool=requirePool(pool.id());ip=nextAvailable(n,pool);}else ip=IpCidr.canonicalAddress(c.requestedAddress());if(!n.cidr().containsAddress(ip)||pool!=null&&!withinPool(ip,pool))throw conflict("DDI_ADDRESS_OUTSIDE_RANGE","address is outside authorized subnet/pool");if(repository.addressInUse(c.vrfId(),ip))throw conflict("DDI_ADDRESS_CONFLICT","address is already allocated/reserved in VRF");var a=IpamAddress.assigned(ids.next(),c.organizationId(),c.vrfId(),n.id(),c.poolId(),ip,c.reservation(),c.hostname(),c.rsotObjectId(),c.dcimEquipmentId(),c.purpose(),clock.instant());repository.insertAddress(a);if(pool!=null&&(c.requestedAddress()==null||c.requestedAddress().isBlank())){String next=incrementWithinPool(ip,pool);repository.updatePool(pool.advance(next,clock.instant()),pool.version());}tx.append(event(c.reservation()?"ddi.ipam.address.reserved.v1":"ddi.ipam.address.allocated.v1",a.id(),a.organizationId(),ctx,"\"address\":\""+json(a.address())+"\",\"vrf_id\":\""+a.vrfId()+"\""));remember(ctx,fp,"address.allocate",a.id());return a;});}
 public IpamAddress release(DomainIdentifier id,long expectedVersion,IpamCommandContext ctx){enabled();String fp=fingerprint("address.release",id,expectedVersion);return execute(tx->{var prior=idempotency.find(ctx.idempotencyKey());if(prior.isPresent())return replayAddress(prior.orElseThrow(),fp,"address.release");IpamAddress current=requireAddress(id);if(current.version()!=expectedVersion)throw conflict("VERSION_CONFLICT","IP address version changed");IpamAddress changed=current.release(clock.instant());repository.updateAddress(changed,expectedVersion);tx.append(event("ddi.ipam.address.released.v1",changed.id(),changed.organizationId(),ctx,"\"address\":\""+json(changed.address())+"\""));remember(ctx,fp,"address.release",changed.id());return changed;});}
 public IpamVrf changeVrfStatus(DomainIdentifier id,long expected,IpamStatus target,IpamCommandContext ctx){return mutateStatus(id,expected,target,ctx,true);} public IpamVlan changeVlanStatus(DomainIdentifier id,long expected,IpamStatus target,IpamCommandContext ctx){enabled();String fp=fingerprint("vlan.status",id,expected,target);return execute(tx->{var prior=idempotency.find(ctx.idempotencyKey());if(prior.isPresent())return replayVlan(prior.orElseThrow(),fp,"vlan.status");IpamVlan current=requireVlan(id);if(current.version()!=expected)throw conflict("VERSION_CONFLICT","VLAN version changed");if(target==IpamStatus.RETIRED&&repository.hasActiveNetworksForVlan(id))throw conflict("DDI_VLAN_IN_USE","VLAN is referenced by active networks");var changed=current.status(target,clock.instant());repository.updateVlan(changed,expected);tx.append(event("ddi.ipam.vlan."+target.wireValue()+".v1",changed.id(),changed.organizationId(),ctx,"\"name\":\""+json(changed.name())+"\""));remember(ctx,fp,"vlan.status",changed.id());return changed;});} public IpamNetwork updateNetwork(DomainIdentifier id,long expected,UpdateNetworkCommand command,IpamCommandContext ctx){enabled();String fp=fingerprint("network.update",id,expected,command);return execute(tx->{var prior=idempotency.find(ctx.idempotencyKey());if(prior.isPresent())return replayNetwork(prior.orElseThrow(),fp,"network.update");IpamNetwork current=requireNetwork(id);if(current.version()!=expected)throw conflict("VERSION_CONFLICT","network version changed");if(command.vlanId()!=null){IpamVlan vlan=requireVlan(command.vlanId());if(!vlan.organizationId().equals(current.organizationId())||vlan.status()!=IpamStatus.ACTIVE)throw conflict("DDI_VLAN_SCOPE_INVALID","network VLAN must be active in the same organization");}var changed=current.metadata(command.vlanId(),command.usage(),command.trustLevel(),clock.instant());repository.updateNetwork(changed,expected);tx.append(event("ddi.ipam.network.updated.v1",changed.id(),changed.organizationId(),ctx,"\"cidr\":\""+json(changed.cidr().value())+"\""));remember(ctx,fp,"network.update",changed.id());return changed;});} public IpamNetwork changeNetworkStatus(DomainIdentifier id,long expected,IpamStatus target,IpamCommandContext ctx){enabled();String fp=fingerprint("network.status",id,expected,target);return execute(tx->{var prior=idempotency.find(ctx.idempotencyKey());if(prior.isPresent())return replayNetwork(prior.orElseThrow(),fp,"network.status");IpamNetwork current=requireNetwork(id);if(current.version()!=expected)throw conflict("VERSION_CONFLICT","network version changed");if(target==IpamStatus.RETIRED&&!repository.addresses(current.organizationId(),current.vrfId(),current.id(),null,1).stream().filter(a->a.status()!=AddressStatus.RELEASED).toList().isEmpty())throw conflict("DDI_NETWORK_IN_USE","network has active allocations");var changed=current.status(target,clock.instant());repository.updateNetwork(changed,expected);tx.append(event("ddi.ipam.network."+target.wireValue()+".v1",changed.id(),changed.organizationId(),ctx,"\"cidr\":\""+json(changed.cidr().value())+"\""));remember(ctx,fp,"network.status",changed.id());return changed;});}
 private IpamVrf mutateStatus(DomainIdentifier id,long expected,IpamStatus target,IpamCommandContext ctx,boolean ignored){enabled();String fp=fingerprint("vrf.status",id,expected,target);return execute(tx->{var prior=idempotency.find(ctx.idempotencyKey());if(prior.isPresent())return replayVrf(prior.orElseThrow(),fp,"vrf.status");IpamVrf current=requireVrf(id);if(current.version()!=expected)throw conflict("VERSION_CONFLICT","VRF version changed");if(target==IpamStatus.RETIRED&&repository.hasActiveNetworks(id))throw conflict("DDI_VRF_IN_USE","VRF contains active networks");var changed=current.status(target,clock.instant());repository.updateVrf(changed,expected);tx.append(event("ddi.ipam.vrf."+target.wireValue()+".v1",changed.id(),changed.organizationId(),ctx,"\"version\":"+changed.version()));remember(ctx,fp,"vrf.status",changed.id());return changed;});}
 public IpamVrf vrf(DomainIdentifier id){enabled();return requireVrf(id);} public IpamVlan vlan(DomainIdentifier id){enabled();return requireVlan(id);} public IpamNetwork network(DomainIdentifier id){enabled();return requireNetwork(id);} public IpamAddress address(DomainIdentifier id){enabled();return requireAddress(id);}
 public List<IpamVrf> vrfs(DomainIdentifier o,int l){return vrfs(o,null,l).items();}
 public List<IpamVlan> vlans(DomainIdentifier o,int l){return vlans(o,null,l).items();}
 public List<IpamNetwork> networks(DomainIdentifier o,DomainIdentifier v,int l){return networks(o,v,null,l).items();}
 public List<IpamPool> pools(DomainIdentifier n,int l){return pools(n,null,l).items();}
 public List<IpamAddress> addresses(DomainIdentifier o,DomainIdentifier v,DomainIdentifier n,int l){return addresses(o,v,n,null,l).items();}
 public CursorPage<IpamVrf> vrfs(DomainIdentifier o,DomainIdentifier after,int l){enabled();int size=bounded(l);return cursorPage(repository.vrfs(o,after,size+1),size,IpamVrf::id);}
 public CursorPage<IpamVlan> vlans(DomainIdentifier o,DomainIdentifier after,int l){enabled();int size=bounded(l);return cursorPage(repository.vlans(o,after,size+1),size,IpamVlan::id);}
 public CursorPage<IpamNetwork> networks(DomainIdentifier o,DomainIdentifier v,DomainIdentifier after,int l){enabled();int size=bounded(l);return cursorPage(repository.networks(o,v,after,size+1),size,IpamNetwork::id);}
 public CursorPage<IpamPool> pools(DomainIdentifier n,DomainIdentifier after,int l){enabled();int size=bounded(l);return cursorPage(repository.pools(n,after,size+1),size,IpamPool::id);}
 public CursorPage<IpamAddress> addresses(DomainIdentifier o,DomainIdentifier v,DomainIdentifier n,DomainIdentifier after,int l){enabled();int size=bounded(l);return cursorPage(repository.addresses(o,v,n,after,size+1),size,IpamAddress::id);}
 private String nextAvailable(IpamNetwork n,IpamPool p){BigInteger first=new BigInteger(1,addressBytes(p.startAddress())),last=new BigInteger(1,addressBytes(p.endAddress())),cursor=new BigInteger(1,addressBytes(p.allocationCursor()));int bits=n.cidr().addressBits();BigInteger size=last.subtract(first).add(BigInteger.ONE),i=cursor;for(BigInteger checked=BigInteger.ZERO;checked.compareTo(size)<0;checked=checked.add(BigInteger.ONE)){String ip=address(i,bits);if(!repository.addressInUse(n.vrfId(),ip))return ip;i=i.equals(last)?first:i.add(BigInteger.ONE);}throw conflict("DDI_POOL_EXHAUSTED","no address is available in pool");}
 private static String incrementWithinPool(String ip,IpamPool p){BigInteger first=new BigInteger(1,addressBytes(p.startAddress())),last=new BigInteger(1,addressBytes(p.endAddress())),x=new BigInteger(1,addressBytes(ip));return address(x.equals(last)?first:x.add(BigInteger.ONE),addressBytes(ip).length*8);}
 private static boolean withinPool(String ip,IpamPool p){BigInteger x=new BigInteger(1,addressBytes(ip)),a=new BigInteger(1,addressBytes(p.startAddress())),b=new BigInteger(1,addressBytes(p.endAddress()));return x.compareTo(a)>=0&&x.compareTo(b)<=0;} private static int compareIp(String a,String b){byte[] aa=addressBytes(a),bb=addressBytes(b);return new BigInteger(1,aa).compareTo(new BigInteger(1,bb));} private static byte[] addressBytes(String ip){try{return java.net.InetAddress.getByName(ip).getAddress();}catch(java.net.UnknownHostException e){throw new IllegalArgumentException("invalid IP",e);}}private static String address(BigInteger value,int bits){byte[] src=value.toByteArray(),dst=new byte[bits/8];int c=Math.min(src.length,dst.length);System.arraycopy(src,src.length-c,dst,dst.length-c,c);try{return java.net.InetAddress.getByAddress(dst).getHostAddress();}catch(java.net.UnknownHostException e){throw new IllegalStateException(e);}}
 private void enabled(){if(!features.ipamEnabled())throw conflict("DDI_IPAM_CAPABILITY_UNAVAILABLE","DDI/IPAM capability is unavailable");} private int bounded(int l){if(l<1||l>500)throw new IllegalArgumentException("limit must be 1..500");return l;} private static <T>CursorPage<T> cursorPage(List<T> rows,int limit,java.util.function.Function<T,DomainIdentifier> id){boolean more=rows.size()>limit;List<T> items=List.copyOf(rows.subList(0,Math.min(limit,rows.size())));DomainIdentifier next=more?id.apply(items.get(items.size()-1)):null;return new CursorPage<>(items,next);} private IpamVrf requireVrf(DomainIdentifier id){return repository.vrf(id).orElseThrow(()->new IpamNotFoundException("VRF"));}private IpamVlan requireVlan(DomainIdentifier id){return repository.vlan(id).orElseThrow(()->new IpamNotFoundException("VLAN"));}private IpamNetwork requireNetwork(DomainIdentifier id){return repository.network(id).orElseThrow(()->new IpamNotFoundException("network"));}private IpamPool requirePool(DomainIdentifier id){return repository.pool(id).orElseThrow(()->new IpamNotFoundException("pool"));}private IpamAddress requireAddress(DomainIdentifier id){return repository.address(id).orElseThrow(()->new IpamNotFoundException("address"));}
 private IpamVrf replayVrf(IpamIdempotencyRepository.Record r,String f,String o){check(r,f,o);return requireVrf(r.resultId());}private IpamVlan replayVlan(IpamIdempotencyRepository.Record r,String f,String o){check(r,f,o);return requireVlan(r.resultId());}private IpamNetwork replayNetwork(IpamIdempotencyRepository.Record r,String f,String o){check(r,f,o);return requireNetwork(r.resultId());}private IpamPool replayPool(IpamIdempotencyRepository.Record r,String f,String o){check(r,f,o);return requirePool(r.resultId());}private IpamAddress replayAddress(IpamIdempotencyRepository.Record r,String f,String o){check(r,f,o);return requireAddress(r.resultId());}private static void check(IpamIdempotencyRepository.Record r,String f,String o){if(!r.operation().equals(o)||!r.payloadSha256().equals(f))throw conflict("IDEMPOTENCY_CONFLICT","idempotency key was used with another payload");}private void remember(IpamCommandContext c,String f,String o,DomainIdentifier id){idempotency.insert(new IpamIdempotencyRepository.Record(c.idempotencyKey(),f,o,id,clock.instant()));}
 private static String optionalCode(String value){if(value==null)return null;String normalized=value.strip();return normalized.isEmpty()?null:normalized;}
 private EventEnvelope event(String t,DomainIdentifier a,DomainIdentifier org,IpamCommandContext c,String fields){return new EventEnvelope(ids.next(),new EventType(t),EVENT_VERSION,clock.instant(),SOURCE,c.correlationId(),a,"{\"id\":\""+a+"\",\"organization_id\":\""+org+"\","+fields+"}");}private static String json(String x){return x.replace("\\","\\\\").replace("\"","\\\"");}private static IpamConflictException conflict(String c,String m){return new IpamConflictException(c,m);}private static String fingerprint(Object...v){try{MessageDigest d=MessageDigest.getInstance("SHA-256");for(Object x:v){d.update(String.valueOf(x).getBytes(StandardCharsets.UTF_8));d.update((byte)0);}return java.util.HexFormat.of().formatHex(d.digest());}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}} private <T>T execute(TransactionalWork<T> w){try{return events.execute(w).value();}catch(TransactionExecutionException e){Throwable c=e.getCause();if(c instanceof IpamConflictException x)throw x;if(c instanceof IpamNotFoundException x)throw x;if(c instanceof IllegalArgumentException x)throw x;throw e;}}
}
